import React, { useState } from 'react';
import './TruckBookingPage.css';

const TruckBookingPage = () => {
  // Cities and their specific background images
  const cityData = {
    "Yamunanagar": "https://images.unsplash.com/photo-1590490359854-dfba19688d70?q=80&w=1500",
    "Kurukshetra": "https://images.unsplash.com/photo-1622313644578-d67065996024?q=80&w=1500",
    "Chandigarh": "https://images.unsplash.com/photo-1595658658481-d53d3f999875?q=80&w=1500",
    "Karnal": "https://images.unsplash.com/photo-1580674285054-bed31e145f59?q=80&w=1500",
    "Ambala": "https://images.unsplash.com/photo-1519003722824-194d4455a60c?q=80&w=1500",
    "Panchkula": "https://images.unsplash.com/photo-1571175432291-fe8a825e3650?q=80&w=1500"
  };

  const [selectedCity, setSelectedCity] = useState("Yamunanagar");

  const vehicles = [
    { id: 1, name: '3 Wheeler', cap: '500kg', price: '160', img: 'https://cdn-icons-png.flaticon.com/512/2155/2155995.png' },
    { id: 2, name: 'Tata Ace', cap: '750kg', price: '205', img: 'https://cdn-icons-png.flaticon.com/512/2156/2156001.png' }
  ];

  const routes = [
    { to: "Karnal", kms: "80 Kms", price: "1500" },
    { to: "Ambala", kms: "50 Kms", price: "1200" },
    { to: "Chandigarh", kms: "100 Kms", price: "2000" },
    { to: "Panipat", kms: "120 Kms", price: "2500" }
  ];

  return (
    <div className="booking-wrapper">
      {/* Hero Section with Dynamic Background */}
      <section 
        className="hero-section" 
        style={{ backgroundImage: `linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url(${cityData[selectedCity]})` }}
      >
        <div className="city-selector-top">
          <select value={selectedCity} onChange={(e) => setSelectedCity(e.target.value)}>
            {Object.keys(cityData).map(city => (
              <option key={city} value={city}>{city}</option>
            ))}
          </select>
        </div>

        <div className="booking-bar-white">
          <div className="form-input">
            <label>Pickup Address *</label>
            <input type="text" placeholder="Enter Pickup Location" />
          </div>
          <div className="form-input">
            <label>Drop Address *</label>
            <input type="text" placeholder="Enter Drop Location" />
          </div>
          <div className="form-input">
            <label>Phone Number *</label>
            <input type="tel" placeholder="Enter Mobile" />
          </div>
          <button className="fare-estimate-btn">
            Get Fare Estimate <span className="arrow">→</span>
          </button>
        </div>
      </section>

      {/* Vehicle Grid Section */}
      <section className="vehicle-selection-area">
        <h2>Book Mini Trucks in {selectedCity}</h2>
        <div className="tabs">
          <button className="active">Light (below 750kg)</button>
          <button>Heavy (above 750kg)</button>
        </div>

        <div className="vehicle-cards-flex">
          {vehicles.map(v => (
            <div key={v.id} className="truck-card">
              <img src={v.img} alt={v.name} />
              <div className="cap-tag">{v.cap}</div>
              <h4>{v.name}</h4>
              <p>Starting from <strong>₹{v.price}</strong></p>
              <a href="#">Know More</a>
            </div>
          ))}
        </div>
      </section>

      {/* Popular Routes Section */}
      <section className="popular-routes">
        <h3>Popular Long Distance Routes from {selectedCity}</h3>
        <div className="routes-grid">
          {routes.map((route, i) => (
            <div key={i} className="route-card">
              <div>
                <strong>to {route.to} ({route.kms})</strong>
                <p>fare from ₹{route.price}</p>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default TruckBookingPage;
